#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run from the repo root wherever the script is started from.
cd "$(dirname "$0")/.."
# PowerShell's plain `bash` is WSL, which has no Node; Git Bash shares Windows' Node.
if ! command -v node >/dev/null 2>&1 || ! command -v npx >/dev/null 2>&1; then
  printf '\n  Node.js is not available in this shell, so the setup cannot run here.\n'
  printf '  From PowerShell, start it with Git Bash instead:\n\n'
  printf '    & "C:\\Program Files\\Git\\bin\\bash.exe" scripts/go-live-setup.sh\n\n'
  exit 1
fi
# Non-secret ids only; the API token never touches disk.
ENV_FILE=".deploy.env"
REPO_URL="https://github.com/joseph-roxas/massage-spa-system"
APP_URL="https://massage-spa-ui.pages.dev"

TOTAL_STAGES=9

banner "Massage Spa System: go-live setup (Cloudflare + GitHub)"

stage "Cloudflare account"
say "The system runs on Cloudflare's free plan. You need one account."
open_url "https://dash.cloudflare.com/sign-up"
step "Sign up (or log in if you already have an account) and verify your email."
step "No credit card is needed; stay on the Free plan."
pause "Press Enter once you can see the Cloudflare dashboard."

stage "Connect this computer to Cloudflare"
say "Next, wrangler (Cloudflare's tool, already installed in this project) asks for permission."
step "A browser tab opens: click Allow."
if confirm "Run 'npx wrangler login' now?"; then
  npx wrangler login
else
  note "Skipped. Run 'npx wrangler login' yourself before the next stage."
fi
pause

stage "Create the database"
say "This creates the production D1 database 'massage-spa-db' (free tier)."
note "If you already created it, answer N and paste its id from 'npx wrangler d1 list'."
D1_GUESS=""
if confirm "Create the database now?"; then
  OUT=$(npx wrangler d1 create massage-spa-db 2>&1) || true
  printf '%s\n' "$OUT" | sed 's/^/    /'
  D1_GUESS=$(printf '%s' "$OUT" | grep -oE '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' | head -n1 || true)
else
  npx wrangler d1 list 2>&1 | sed 's/^/    /' || true
fi
[[ -n "$D1_GUESS" ]] && say "Found database id: ${BOLD}$D1_GUESS${RESET}"
ask D1_DATABASE_ID "Database id (the long id with dashes${D1_GUESS:+, Enter for the one above}):"
[[ -z "$D1_DATABASE_ID" && -n "$D1_GUESS" ]] && D1_DATABASE_ID="$D1_GUESS"
write_env D1_DATABASE_ID "$D1_DATABASE_ID"

stage "Account id"
say "Your Cloudflare account id is shown below (also on the dashboard's right sidebar)."
npx wrangler whoami 2>&1 | sed 's/^/    /' || true
ask CLOUDFLARE_ACCOUNT_ID "Account ID (32 letters and numbers):"
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"

stage "API token for GitHub"
say "GitHub needs a token to deploy to Cloudflare for you."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Click 'Create Token', then 'Use template' next to 'Edit Cloudflare Workers'."
step "Under Permissions click '+ Add more' and add:  Account · D1 · Edit"
step "Add one more:  Account · Cloudflare Pages · Edit"
step "Account Resources: Include · your account.  Zone Resources: Include · All zones."
step "Click 'Continue to summary', then 'Create Token'."
step "Copy the token now: Cloudflare shows it only once. Keep it copied for the next stage."
note "Menu names can shift slightly over time; pick the closest match."
pause "Press Enter once the token is copied."

stage "Give GitHub the keys"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  ask_secret CLOUDFLARE_API_TOKEN "Paste the API token (hidden):"
  set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
  set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  set_var D1_DATABASE_ID "$D1_DATABASE_ID"
else
  say "Add two secrets and one variable on GitHub (names must match exactly)."
  open_url "$REPO_URL/settings/secrets/actions"
  step "Secrets tab → 'New repository secret':"
  step "   Name ${BOLD}CLOUDFLARE_API_TOKEN${RESET}   Secret: paste the token you copied"
  step "   Name ${BOLD}CLOUDFLARE_ACCOUNT_ID${RESET}  Secret: ${BOLD}$CLOUDFLARE_ACCOUNT_ID${RESET}"
  step "Variables tab → 'New repository variable':"
  step "   Name ${BOLD}D1_DATABASE_ID${RESET}         Value: ${BOLD}$D1_DATABASE_ID${RESET}"
  pause "Press Enter once all three are saved."
fi

stage "Deploy everything"
say "This builds and publishes the database, API and app (takes about 5 minutes)."
open_url "$REPO_URL/actions/workflows/deploy-all.yml"
step "Click 'Run workflow' (right side), keep branch 'main', click the green 'Run workflow'."
step "Wait until all three jobs (db, api, ui) show a green check."
note "If one turns red, open it and read the last lines; it is usually a misspelled secret name."
pause "Press Enter once the run is green."

stage "Your Super Admin login"
say "Creates your login on the live system. It asks for your name, email and a password."
note "Email defaults to desiree.ababon@gmail.com. Run this stage again any time to reset the password."
if confirm "Create the Super Admin on the live database now?"; then
  D1_DATABASE_ID="$D1_DATABASE_ID" npm run admin:create -w API -- --remote
else
  note "Later: D1_DATABASE_ID=$D1_DATABASE_ID npm run admin:create -w API -- --remote"
fi
pause

stage "Open the system"
open_url "$APP_URL"
step "Log in with the email and password you just set."
step "Open ${BOLD}Go-live${RESET} in the menu and work through the checklist:"
step "   staff and PINs, the receptionist's rate, her login, stock count, CA balances."
step "Bookmark $APP_URL on the front-desk computer."
pause "Press Enter to finish."

finish
say "App:      $APP_URL"
say "Database: $D1_DATABASE_ID (saved in $ENV_FILE, not uploaded)"
}

run_wizard "$@"; exit
